describe('Tab Navigation URL Hash Update', () => {
  beforeEach(() => {
    cy.visit('/tabs');
  });

  it('should update URL hash when tab is selected', () => {
    // Verify initial URL hash
    cy.url().should('include', '#tab1');

    // Click on tab 2
    cy.get('[data-testid="tab-2"]').click();

    // Verify URL hash has changed to #tab2
    cy.url().should('include', '#tab2');

    // Verify tab content is displayed for tab 2
    cy.get('[data-testid="tab-content-2"]').should('be.visible');

    // Verify tab 1 is not visible
    cy.get('[data-testid="tab-content-1"]').should('not.be.visible');

    // Verify tab 2 content is visible
    cy.get('[data-testid="tab-content-2"]').should('be.visible');
  });

  it('should handle URL hash with special characters', () => {
    // Navigate to a tab with special characters in hash
    cy.visit('/tabs#tab3%40');

    // Verify URL hash contains special characters
    cy.url().should('include', '#tab3%40');

    // Click on tab 4
    cy.get('[data-testid="tab-4"]').click();

    // Verify URL hash has been updated correctly
    cy.url().should('include', '#tab4');

    // Verify tab content is displayed for tab 4
    cy.get('[data-testid="tab-content-4"]').should('be.visible');

    // Verify previous tab content is not visible
    cy.get('[data-testid="tab-content-3%40"]').should('not.be.visible');

    // Verify tab 4 content is visible
    cy.get('[data-testid="tab-content-4"]').should('be.visible');
  });
});
